import sys; sys.path.insert(0, ".")
from duration import parse_duration as p

ok = {
 "1h30m": 5400, " 2d 4h ": 187200, "1.5h": 5400, "1w2d3h4m5s": 788645,
 "1:02:03": 3723, "-45s": -45, "0": 0,
 "1h 30m": 5400, "05m": 300, "1.5m": 90, "0.1h": 360, "0.25h": 900,
 "1:30": 90, "1:00:00": 3600, "90:00": 5400, "-1h": -3600, "-1:30": -90,
 "-0s": 0, "1w": 604800, "1d1h1m1s": 90061, "1.5s": None,
}
for k, v in ok.items():
    if v is None:
        try: p(k); raise SystemExit(f"should fail: {k!r}")
        except ValueError: pass
        continue
    assert p(k) == v, (k, p(k), v)

bad = ["", "   ", "-", ".5h", "5.h", "30m1h", "1h1h", "1 h", "1h  30m", "1h,30m",
       "0.3s", "1:60", "1:5", "1:5:00", "1.5:00", "1:00:60", "+1h", "5", "1.5", "00",
       "-0", "0.0", "1H", "1x", "1h-30m", "- 1h", "--1h", "1:30.5", " 1 : 30 ",
       "1h\t30m", "\n", "1.5.5h", "h", "1:2:3:4", "5m5m", "1m1d"]
for b in bad:
    try: r = p(b)
    except ValueError: continue
    raise SystemExit(f"should be invalid: {b!r} -> {r}")

for t in [None, 5, 1.5, b"1h"]:
    try: p(t); raise SystemExit(f"no TypeError for {t!r}")
    except TypeError: pass

print("all checks passed")
